Lemma sdiv_run (fx : FPState) R M (a i : Z) :
  getr R (reg 17) = Z_to_bv 64 (2 ^ 64 - a) -> getr R (reg 12) = Z_to_bv 64 MS -> getr R (reg 9) = Z_to_bv 64 i ->
  1 <= a <= 2 ^ 63 -> 0 <= i < 2 ^ 32 ->
  exists R', msteps RSEGS (mst fx R 0x3d1c0 M) (mst fx R' 0x3d1d4 M)
    /\ getr R' (reg 17) = Z_to_bv 64 (- (a / 10)) /\ getr R' (reg 9) = Z_to_bv 64 (i + 1) /\ getr R' (reg 7) = Z_to_bv 64 1
