Lemma back_branch_p (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (i : Z) :
  getr R (reg 16) = Z_to_bv 64 i -> getr R (reg 14) = Z_to_bv 64 254 -> 0 <= i <= 18 ->
  msteps RSEGS (mst fx R 0x3d190 M) (mst fx R 0x3d164 M).
Proof.
