Lemma digit_edenot_n (EE : AX2.env) (a q : Z) :
  bv_unsigned (AX2.ev EE 39%nat) = 2 ^ 64 - a -> bv_unsigned (AX2.ev EE 55%nat) = q -> q = (- (a / 10)) mod 2 ^ 64 -> 1 <= a <= 2 ^ 63 ->
  bv_unsigned (AX2.edenot EE (AX2.EAlu Instr.ALU_ADD (AX2.EAluw Instr.ALU_SUB (AX2.EMd Instr.M_MUL (AX2.ELit 10) (AX2.EVar 55)) (AX2.EVar 39)) (AX2.ELit 48)))
  = 48 + a mod 10.
Proof.
