Lemma frame_piece Ma Mb (lo n : Z) :
  sp1 - 320 <= lo -> lo + n <= sp1 -> cm Ma -> world Ma -> adaptor_at Ma oa ov (stK kx kgx) -> AG Ma -> mem_grows Ma Mb ->
  (forall i, 0 <= i < 2 ^ 64 -> ~ (lo <= i < lo + n) -> Mb (Z_to_bv 64 i) = Ma (Z_to_bv 64 i)) ->
