Lemma PLOOP (j : nat) : forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (ky : PM.vstr) (kgy : Z) (cr : credit) (d cnt : Z) (ds : list Z),
  (Z.of_nat j <= 18)%Z -> 0 <= d < 256 -> 0 <= cnt <= 100 ->
  getr R (reg 1) = Z_to_bv 64 0x3d22c -> getr R (reg 2) = Z_to_bv 64 (sp1 - 320) -> getr R (reg 8) = Z_to_bv 64 (oa + 24) -> getr R (reg 9) = Z_to_bv 64 cnt ->
  getr R (reg 10) = Z_to_bv 64 (oa + 24) -> getr R (reg 11) = Z_to_bv 64 d ->
  getr R (reg 18) = Z_to_bv 64 (sp1 - 295 + Z.of_nat j) -> getr R (reg 19) = Z_to_bv 64 (sp1 - 295) -> kept R ->
  saves M -> cm M -> world M -> AG M -> ABK M -> ERK M -> adaptor_at M oa ov (stK ky kgy) -> kcontent M (oa + 24) ky (bs0 ++ ds) -> NEM.ascii ds -> d < 128 -> DG M (Z.of_nat j) ->
  PQM.ks_ok PQM.SMK ky kgy -> PM.vs_size ky + Z.of_nat j + 1 = T ->
  PMSP.credit_keep cr1 cr (PQM.pot_adaptor L (stK kx kgx)) (PQM.pot_adaptor L (stK ky kgy)) -> model_but_vm model1 model ->
  hi_heap HI (PQM.aown (stK ky kgy) ++ LBX) cr M (m_vmmaps model) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x66444 M model) K.
