(* [comment removed for export] *)
Lemma FROMI (fx0 : FPState) (R0 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (cr1 : credit)
      (sp1 ra v : Z) (lvX : list PQM.alvl) (bX kX : Z) (kx : PM.vstr) (kgx : Z) (kbx : PM.vstr) (gx : Z) (bs0 : list Z) :
  S - 3776 <= sp1 -> sp1 <= S -> sp1 mod 16 = 0 ->
  getr R0 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R0 (reg 2) = Z_to_bv 64 sp1 -> getr R0 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R0 (reg 4) = Z_to_bv 64 (pa_tp AD) ->
  getr R0 (reg 10) = Z_to_bv 64 v -> 0 <= v < 2 ^ 64 -> getr R0 (reg 11) = Z_to_bv 64 (oa + 24) ->
  cm M1 -> world M1 -> adaptor_at M1 oa ov (PQM.AST lvX bX kX kx kgx kbx gx) -> kcontent M1 (oa + 24) kx bs0 -> PQM.ks_ok PQM.SMK kx kgx -> PQM.ks_ok PQM.SMB kbx gx -> PM.vs_size kx + 21 <= PQM.SMK ->
  PMSP.credit_le (PQM.pot_adaptor L (PQM.AST lvX bX kX kx kgx kbx gx)) cr1 -> PMSP.model_ok model1 ->
  hi_heap HI (PQM.aown (PQM.AST lvX bX kX kx kgx kbx gx) ++ LBX) cr1 M1 (m_vmmaps model1) ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (kx' : PM.vstr) (kgx' : Z) (cr' : credit) (ds : list Z),
      regs_preserved R0 R' -> cm M' -> world M' ->
      (forall a m, sp1 <= a -> a + m <= 2 ^ 64 -> (a + m <= oa + 24 \/ oa + 48 <= a) -> L5C.agree_on M1 M' a m) ->
      (forall B m, In (B, m) (PQM.lvec_own bX kX ++ PM.vs_own kbx ++ LBX) -> L5C.agree_on M1 M' B m) -> (forall e, PQST.err_ok RSEGS AD AQ M1 e -> PQST.err_ok RSEGS AD AQ M' e) ->
      adaptor_at M' oa ov (PQM.AST lvX bX kX kx' kgx' kbx gx) -> kcontent M' (oa + 24) kx' (bs0 ++ ds) -> NEM.ascii ds -> PQM.ks_ok PQM.SMK kx' kgx' -> PM.vs_size kx' = PM.vs_size kx + nchars v ->
      PMSP.credit_keep cr1 cr' (PQM.pot_adaptor L (PQM.AST lvX bX kX kx kgx kbx gx)) (PQM.pot_adaptor L (PQM.AST lvX bX kX kx' kgx' kbx gx)) ->
      model_but_vm model1 model' -> hi_heap HI (PQM.aown (PQM.AST lvX bX kX kx' kgx' kbx gx) ++ LBX) cr' M' (m_vmmaps model') ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' ra M' model') K) ->
